import{c as a,Q as s,j as e,m as i}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuRandomTeleport 插件联动","description":"","frontmatter":{"title":"YuRandomTeleport 插件联动"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/api.md","filePath":"plugins/items/yu-random-teleport/api.md"}'),d={name:"plugins/items/yu-random-teleport/api.md"};function l(o,t,n,p,r,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="yurandomteleport-插件联动" tabindex="-1">YuRandomTeleport 插件联动 <a class="header-anchor" href="#yurandomteleport-插件联动" aria-label="Permalink to &quot;YuRandomTeleport 插件联动&quot;">​</a></h1><p>YuRandomTeleport 当前没有公开的 Java API 文档，主要通过 Bukkit 命令、Vault 经济、配置回调命令和消息文件完成联动。对大多数服务器而言，这些入口已经能覆盖经济扣费、反馈展示、日志记录、任务触发和活动系统接入。</p><h2 id="vault-经济" tabindex="-1">Vault 经济 <a class="header-anchor" href="#vault-经济" aria-label="Permalink to &quot;Vault 经济&quot;">​</a></h2><p>插件将 Vault 作为软依赖：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">softdepend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Vault</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>启用经济后，插件会通过 Bukkit ServicesManager 查找 <code>Economy</code> 服务。扣费逻辑发生在成功传送后：</p><ol><li>读取当前世界费用。</li><li>检查玩家余额是否足够。</li><li>找到安全位置并成功传送。</li><li>调用 Vault 扣除费用。</li><li>向玩家发送扣费后的余额消息。</li></ol><p>如果没有安装 Vault，或 Vault 没有经济服务提供者，插件会输出提示并跳过经济扣费。</p><h2 id="bstats-统计" tabindex="-1">bStats 统计 <a class="header-anchor" href="#bstats-统计" aria-label="Permalink to &quot;bStats 统计&quot;">​</a></h2><p>插件内置 bStats Bukkit 统计：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pluginId: 30589</span></span></code></pre></div><p>bStats 只用于插件使用统计，不参与传送逻辑。若服务器侧禁用了 bStats，随机传送功能仍可正常工作。</p><h2 id="控制台命令回调" tabindex="-1">控制台命令回调 <a class="header-anchor" href="#控制台命令回调" aria-label="Permalink to &quot;控制台命令回调&quot;">​</a></h2><p>配置文件的 <code>commands</code> 区块是最常用的联动入口：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  on-teleport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;title {player} title {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">随机传送</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">color</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yellow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  on-success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;broadcast {player} 已随机传送到 {world}: {x}, {z}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  on-fail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;say {player} 随机传送失败: {reason}&quot;</span></span></code></pre></div><p>适合接入：</p><table tabindex="0"><thead><tr><th>系统</th><th>示例</th></tr></thead><tbody><tr><td>Title/ActionBar 插件</td><td>在传送开始或成功后显示提示。</td></tr><tr><td>任务系统</td><td>成功 RTP 后推进任务目标。</td></tr><tr><td>日志系统</td><td>记录玩家随机传送世界和坐标。</td></tr><tr><td>活动系统</td><td>活动期间传送成功后发放奖励或加入队列。</td></tr><tr><td>权限系统</td><td>在特定阶段临时添加或移除权限。</td></tr></tbody></table><p>命令由控制台同步执行，写配置时不要在命令前添加 <code>/</code>。</p><h2 id="消息文件" tabindex="-1">消息文件 <a class="header-anchor" href="#消息文件" aria-label="Permalink to &quot;消息文件&quot;">​</a></h2><p><code>messages.yml</code> 支持自定义全部玩家消息和后台日志文本。常用键包括：</p><table tabindex="0"><thead><tr><th>消息键</th><th>用途</th></tr></thead><tbody><tr><td><code>prefix</code></td><td>聊天前缀。</td></tr><tr><td><code>cooldown</code></td><td>玩家仍在冷却。</td></tr><tr><td><code>teleport-countdown</code></td><td>等待倒计时。</td></tr><tr><td><code>teleport-cancelled</code></td><td>等待期间被打断。</td></tr><tr><td><code>teleport-success</code></td><td>成功传送。</td></tr><tr><td><code>no-safe-location</code></td><td>未找到安全位置。</td></tr><tr><td><code>insufficient-funds</code></td><td>余额不足。</td></tr><tr><td><code>world-blacklisted</code></td><td>世界在黑名单中。</td></tr><tr><td><code>world-not-whitelisted</code></td><td>世界不在白名单中。</td></tr><tr><td><code>reload-success</code></td><td>重载成功。</td></tr></tbody></table><p>消息内容支持 <code>{seconds}</code>、<code>{cost}</code>、<code>{x}</code>、<code>{z}</code>、<code>{world}</code> 等对应占位符，具体以默认 <code>messages.yml</code> 为准。</p><h2 id="与权限插件联动" tabindex="-1">与权限插件联动 <a class="header-anchor" href="#与权限插件联动" aria-label="Permalink to &quot;与权限插件联动&quot;">​</a></h2><p>YuRandomTeleport 使用 Bukkit 权限系统，因此可以直接与 LuckPerms、GroupManager、PermissionsEx 等权限插件配合。</p><p>常用 LuckPerms 示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lp group default permission set yurtp.use true</span></span>
<span class="line"><span>lp group admin permission set yurtp.reload true</span></span>
<span class="line"><span>lp group admin permission set yurtp.teleport.others true</span></span>
<span class="line"><span>lp group vip permission set yurtp.bypass.cooldown true</span></span></code></pre></div><h2 id="与世界管理插件联动" tabindex="-1">与世界管理插件联动 <a class="header-anchor" href="#与世界管理插件联动" aria-label="Permalink to &quot;与世界管理插件联动&quot;">​</a></h2><p>插件按 Bukkit 世界名读取配置。与 Multiverse-Core、MyWorlds 或服务端原生多世界一起使用时，应确保配置中的世界名与 Bukkit 加载后的世界名完全一致。</p><p>如果世界由其他插件动态加载，建议在世界加载完成后再测试 <code>/rtp</code>，否则命令中的世界名不会出现在 Tab 补全中。</p><h2 id="与保护或战斗插件联动" tabindex="-1">与保护或战斗插件联动 <a class="header-anchor" href="#与保护或战斗插件联动" aria-label="Permalink to &quot;与保护或战斗插件联动&quot;">​</a></h2><p>YuRandomTeleport 自身不会检查 WorldGuard 区域、领地或战斗标签。推荐做法：</p><table tabindex="0"><thead><tr><th>需求</th><th>建议</th></tr></thead><tbody><tr><td>禁止主城 RTP</td><td>使用 <code>world-blacklist</code> 或 <code>world-whitelist</code>。</td></tr><tr><td>禁止战斗逃跑</td><td>保持 <code>teleport.wait-seconds</code> 大于 <code>0</code>，并开启 <code>cancel-on-move</code>。</td></tr><tr><td>更严格的战斗限制</td><td>使用战斗插件在战斗状态下临时移除 <code>yurtp.use</code> 或拦截命令。</td></tr><tr><td>禁止落入受保护区域</td><td>使用独立资源世界，或通过更小的半径和安全方块白名单控制落点。</td></tr></tbody></table><h2 id="文件系统行为" tabindex="-1">文件系统行为 <a class="header-anchor" href="#文件系统行为" aria-label="Permalink to &quot;文件系统行为&quot;">​</a></h2><p>插件会读写：</p><ul><li><code>plugins/YuRandomTeleport/config.yml</code></li><li><code>plugins/YuRandomTeleport/messages.yml</code></li><li>配置升级备份文件，例如 <code>config.yml.bak4</code></li><li>损坏配置备份，例如 <code>config.yml.broken</code></li></ul><p>插件不会在默认配置下写入数据库或外部文件。</p>`,36)])])}const u=a(d,[["render",l]]);export{k as __pageData,u as default};
